Certificate expiry checker: test the clock, not the certs. Save /workspace/certwatch.py:

from datetime import datetime, timezone, timedelta

def classify(not_after: datetime, now=None):
    now = now or datetime.now(timezone.utc)
    remaining = not_after - now
    if remaining <= timedelta(0):
        return "expired"
    if remaining <= timedelta(days=7):
        return "critical"
    if remaining <= timedelta(days=30):
        return "warning"
    return "ok"

def summarize(certs, now=None):
    now = now or datetime.now(timezone.utc)
    out = {"expired": [], "critical": [], "warning": [], "ok": []}
    for name, not_after in sorted(certs.items()):
        out[classify(not_after, now)].append(name)
    return out

